package org.apache.commons.cli;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.util.Collection;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class OptionGroup_ESTest_test04 extends OptionGroup_ESTest_scaffolding {

    /**
     * Selecting the same option twice in a group is allowed: the second
     * setSelected call simply re-selects the option already chosen, so no
     * AlreadySelectedException is thrown.
     */
    @Test(timeout = 4000)
    public void reselectingSameOptionDoesNotThrow() throws Throwable {
        OptionGroup optionGroup = new OptionGroup();
        Option option = new Option((String) null, "[]", true, (String) null);

        optionGroup.setSelected(option);
        // Re-selecting the same option is a no-op, not a conflict.
        optionGroup.setSelected(option);

        // The option was never given a value separator, so it keeps the
        // default: the null character '�'.
        assertEquals('�', option.getValueSeparator());
    }
}
